css:
.stage {
  position: relative;
  min-height: 280px;
  padding: 16px;
  border: 2px dashed #a1a1aa;
  overflow: hidden;
}

.page {
  margin: 0;
}

.backdrop {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  background: rgb(24 24 27 / 0.5);
}

.dialog {
  padding: 16px 24px;
  background: #fed7aa;
  border: 1px solid #f97316;
  border-radius: 6px;
}
